327	
328	    fn key(instance: u64, node_id: i32) -> ExchangeKey {
329	        ExchangeKey {
330	            fragment_instance_id: FragmentInstanceId::from_halves(7, instance as i64),
331	            node_id,
332	        }
333	    }
334	
335	    /// The rendezvous only stores the params, so an empty shell is enough here.
336	    fn params() -> TExecPlanFragmentParams {
337	        TExecPlanFragmentParams {
338	            protocol_version: InternalServiceVersion::V1,
339	            fragment: None,
340	            desc_tbl: None,
341	            params: None,
342	            coord: None,
343	            backend_num: None,
344	            query_globals: None,
345	            query_options: None,
346	            enable_profile: None,
347	            resource_info: None,
348	            import_label: None,
349	            db_name: None,
350	            load_job_id: None,
351	            load_error_hub_info: None,
352	            is_pipeline: None,
353	            pipeline_dop: None,
354	            per_scan_node_dop: None,
355	            workgroup: None,
356	            enable_resource_group: None,
357	            func_version: None,
358	            enable_shared_scan: None,
359	            is_stream_pipeline: None,
360	            adaptive_dop_param: None,
361	            group_execution_scan_dop: None,
