367	
368	    fn names() -> Vec<String> {
369	        vec!["id".to_string(), "name".to_string()]
370	    }
371	
372	    fn staged(fill: u8) -> StagedBatch {
373	        StagedBatch {
374	            metadata: vec![fill; 4],
375	            offset: u64::from(fill) * 1024,
376	            len: 512,
377	            rows: Some(u64::from(fill)),
378	        }
379	    }
380	
381	    fn local_slot(key: ExchangeKey, sender_id: i32) -> SenderSlot {
382	        SenderSlot {
383	            fragment_instance_id: key.fragment_instance_id,
384	            node_id: key.node_id,
385	            sender_id,
386	        }
387	    }
