389	    /// Remote frames accumulate in sequence order; only the eos completes the sender, and the
390	    /// batches come out in arrival order.
391	    #[test]
392	    fn remote_frames_accumulate_and_eos_completes_the_set() {
393	        let exchange = LocalExchange::default();
394	        let key = key(1, 7);
395	
396	        assert!(
397	            exchange
398	                .push_remote_frame(key, 0, 0, false, names(), Some(staged(1)))
399	                .unwrap()
400	                .is_none()
401	        );
402	        assert!(
403	            exchange
404	                .push_remote_frame(key, 0, 1, false, names(), Some(staged(2)))
405	                .unwrap()
406	                .is_none()
407	        );
408	        // The receiver registers mid-stream; still not ready, the sender has not closed.
409	        assert!(
410	            exchange
411	                .register_receiver(key.fragment_instance_id, vec![(7, 1)], params())
412	                .unwrap()
413	                .is_none()
414	        );
415	
416	        let ready = exchange
417	            .push_remote_frame(key, 0, 2, true, names(), None)
418	            .unwrap()
419	            .expect("eos completes the sender set");
420	        assert_eq!(ready.inputs.len(), 1);
421	        assert_eq!(ready.inputs[0].node_id, 7);
422	        let SenderSource::Remote {
423	            names: got_names,
424	            sender_id,
425	            batches,
426	            closed,
427	        } = &ready.inputs[0].sources[0]
428	        else {
429	            panic!("expected a remote source");
430	        };
431	        assert_eq!(got_names, &names());
432	        assert_eq!(*sender_id, 0);
433	        assert!(*closed);
434	        assert_eq!(batches, &vec![staged(1), staged(2)]);
435	    }
436	
437	    /// A replayed frame (brpc reconnect-retry) is dropped idempotently, even after eos.
438	    #[test]
439	    fn duplicate_remote_seq_is_dropped_idempotently() {
440	        let exchange = LocalExchange::default();
441	        let key = key(2, 7);
442	        exchange
443	            .push_remote_frame(key, 0, 0, false, names(), Some(staged(1)))
444	            .unwrap();
445	        assert!(
446	            exchange
447	                .push_remote_frame(key, 0, 0, false, names(), Some(staged(1)))
448	                .unwrap()
449	                .is_none(),
450	            "replayed data frame is dropped"
451	        );
452	        exchange
453	            .push_remote_frame(key, 0, 1, true, names(), None)
454	            .unwrap();
455	        assert!(
456	            exchange
457	                .push_remote_frame(key, 0, 1, true, names(), None)
458	                .unwrap()
459	                .is_none(),
460	            "replayed eos frame is dropped"
461	        );
462	        // The single staged batch survived, un-duplicated.
463	        let ready = exchange
464	            .register_receiver(key.fragment_instance_id, vec![(7, 1)], params())
465	            .unwrap()
466	            .expect("sender already complete");
467	        let SenderSource::Remote { batches, .. } = &ready.inputs[0].sources[0] else {
468	            panic!("expected a remote source");
469	        };
470	        assert_eq!(batches.len(), 1);
471	    }
472	
473	    /// A sequence gap means a frame was lost; the query must fail rather than lose rows.
474	    #[test]
475	    fn remote_seq_gap_is_a_loud_error() {
476	        let exchange = LocalExchange::default();
477	        let key = key(3, 7);
478	        exchange
479	            .push_remote_frame(key, 0, 0, false, names(), Some(staged(1)))
480	            .unwrap();
481	        let err = exchange
482	            .push_remote_frame(key, 0, 2, false, names(), Some(staged(2)))
483	            .unwrap_err();
484	        assert!(err.contains("skipped from frame seq 1 to 2"), "{err}");
485	    }
486	
487	    /// A new frame after eos is a protocol violation, never a silent append.
488	    #[test]
489	    fn remote_frame_after_eos_is_a_loud_error() {
490	        let exchange = LocalExchange::default();
491	        let key = key(4, 7);
492	        exchange
493	            .push_remote_frame(key, 0, 0, true, names(), None)
494	            .unwrap();
495	        let err = exchange
496	            .push_remote_frame(key, 0, 1, false, names(), Some(staged(1)))
497	            .unwrap_err();
498	        assert!(err.contains("after eos"), "{err}");
499	    }
500	
501	    /// All frames of one sender must agree on the column names.
502	    #[test]
503	    fn remote_names_must_match_across_frames() {
504	        let exchange = LocalExchange::default();
505	        let key = key(5, 7);
506	        exchange
507	            .push_remote_frame(key, 0, 0, false, names(), Some(staged(1)))
508	            .unwrap();
509	        let err = exchange
510	            .push_remote_frame(key, 0, 1, false, vec!["other".to_string()], Some(staged(2)))
511	            .unwrap_err();
512	        assert!(err.contains("changed its column names"), "{err}");
513	    }
514	
515	    /// Frames must carry names (the receiver binds its stream schema from them) and either a
516	    /// batch or eos.
517	    #[test]
518	    fn remote_frame_shape_is_validated() {
519	        let exchange = LocalExchange::default();
520	        let key = key(6, 7);
521	        let err = exchange
522	            .push_remote_frame(key, 0, 0, false, Vec::new(), Some(staged(1)))
523	            .unwrap_err();
524	        assert!(err.contains("without column names"), "{err}");
525	        let err = exchange
526	            .push_remote_frame(key, 0, 0, false, names(), None)
527	            .unwrap_err();
528	        assert!(err.contains("neither a batch nor eos"), "{err}");
529	    }
530	
531	    /// A fan-in of one local parked sender and one remote sender becomes ready only when the
532	    /// local sender has parked AND the remote sender has closed.
533	    #[test]
534	    fn mixed_local_and_remote_sender_set() {
535	        let exchange = LocalExchange::default();
536	        let key = key(8, 7);
537	        assert!(
538	            exchange
539	                .register_receiver(key.fragment_instance_id, vec![(7, 2)], params())
540	                .unwrap()
541	                .is_none()
542	        );
543	        assert!(
544	            exchange
545	                .push_sender(
546	                    key,
547	                    0,
548	                    SenderSource::LocalParked {
549	                        names: names(),
550	                        slot: local_slot(key, 0),
551	                    },
552	                )
553	                .unwrap()
554	                .is_none()
555	        );
556	        assert!(
557	            exchange
558	                .push_remote_frame(key, 1, 0, false, names(), Some(staged(3)))
559	                .unwrap()
560	                .is_none(),
561	            "an open remote sender must not count as complete"
562	        );
563	        let ready = exchange
564	            .push_remote_frame(key, 1, 1, true, names(), None)
565	            .unwrap()
566	            .expect("both senders now complete");
567	        assert_eq!(ready.inputs[0].sources.len(), 2);
568	        assert!(matches!(
569	            ready.inputs[0].sources[0],
570	            SenderSource::LocalParked { .. }
571	        ));
572	        assert!(matches!(
573	            ready.inputs[0].sources[1],
574	            SenderSource::Remote { sender_id: 1, .. }
575	        ));
576	    }
577	
578	    /// A remote frame colliding with an already-parked local sender of the same id is a bug in
579	    /// the sender set, reported loudly.
580	    #[test]
581	    fn remote_frame_colliding_with_local_sender_is_an_error() {
582	        let exchange = LocalExchange::default();
583	        let key = key(9, 7);
584	        exchange
585	            .push_sender(
586	                key,
587	                0,
588	                SenderSource::LocalParked {
589	                    names: names(),
590	                    slot: local_slot(key, 0),
591	                },
592	            )
593	            .unwrap();
594	        let err = exchange
595	            .push_remote_frame(key, 0, 0, false, names(), Some(staged(1)))
596	            .unwrap_err();
597	        assert!(err.contains("collides with a local parked sender"), "{err}");
598	    }
599	}

  1	//! In-memory buffer of executed-fragment results awaiting FE `fetch_data` collection.
  2	//!
  3	//! StarRocks dispatches a fragment with `exec_plan_fragment`, then polls `fetch_data` with the
  4	//! fragment instance id until end-of-stream. This store bridges those two RPCs: the exec handler
  5	//! buffers a fragment's rows here, and each `fetch_data` poll drains them.
  6	
  7	use std::fmt;
  8	use std::{collections::HashMap, sync::Mutex};
  9	
 10	use starrocks_thrift::data::TResultBatch;
 11	use starrocks_thrift::types::TUniqueId;
 12	use uuid::Uuid;
 13	
 14	use crate::proto::starrocks::PUniqueId;
 15	
 16	/// StarRocks `fragment_instance_id`, the key the FE passes to `fetch_data`.
 17	///
 18	/// StarRocks identifies a fragment instance by a 128-bit id split into `hi`/`lo`
 19	/// 64-bit halves (thrift `TUniqueId` on dispatch, proto `PUniqueId` on
 20	/// `fetch_data`). It is held here as a [`Uuid`] so the two wire forms compare
 21	/// equal and logs render the canonical hyphenated form instead of `hi-lo`.
 22	#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
 23	pub struct FragmentInstanceId(Uuid);
 24	
 25	impl FragmentInstanceId {
 26	    /// Packs the `hi`/`lo` 64-bit halves of a StarRocks unique id into a [`Uuid`].
 27	    pub(crate) fn from_halves(hi: i64, lo: i64) -> Self {
 28	        Self(Uuid::from_u64_pair(hi as u64, lo as u64))
 29	    }
 30	
 31	    /// The `hi`/`lo` halves back out, for proto messages that carry them (`PUniqueId`).
