117	   117	/// GPU-backed [`FragmentExecutor`] running plans on an embedded Sirius engine.
118	   118	///
119	   119	/// The engine context lives on a dedicated thread; this handle forwards plans to it and waits for
120	   120	/// the result. Dropping it closes the request channel, which ends the thread and tears the context
121	   121	/// down (joined for an ordered teardown).
122	   122	#[derive(Debug)]
123	   123	pub struct SiriusEngine {
124	   124	    /// Sender to the engine thread. `Mutex<Option<..>>` makes the `!Sync` sender shareable and
125	   125	    /// lets `Drop` close the channel before joining; sends are brief (the thread serializes work).
126	   126	    requests: Mutex<Option<Sender<EngineRequest>>>,
127	   127	    /// Engine thread handle, taken and joined on drop.
128	   128	    thread: Mutex<Option<JoinHandle<()>>>,
129	   129	    /// Thread-safe staging-arena handle (`None` when `SIRIUS_EXCHANGE_STAGING_BYTES` is unset),
130	   130	    /// serving every `staging_*` call directly on the caller's thread.
131	   131	    ///
132	   132	    /// INVARIANT: staging leases must never funnel through `requests` — a fragment wedged
133	   133	    /// inside `run()` would starve every peer's `request_staging_lease` and stall their
134	   134	    /// cross-CN exchanges. Off-thread service is safe because lease/release/base/capacity only
135	   135	    /// take the arena's internal mutex and make no CUDA calls; the engine thread keeps its own
136	   136	    /// direct arena access (`Context::staging_release` for remote-input leases, and
137	   137	    /// `export_packed` leasing internally) — one shared C++ allocator, two entry points.
138	   138	    staging: Option<sirius::StagingArena>,
139	   139	}
