142	   142	    /// Brings up the engine on a dedicated thread (fail-fast) and returns a handle.
143	   143	    ///
144	   144	    /// Blocks until the context is initialized — or bring-up fails — so a bad config or GPU
145	   145	    /// failure surfaces here, before any RPC is served. `settings` carries the resolved Sirius
146	   146	    /// YAML path (built-in defaults when `None`), the engine artifact directory, and the CUDA
147	   147	    /// device pin.
148	   148	    pub fn start(settings: EngineSettings) -> Result<Self, String> {
149	   149	        Self::configure_duckdb_extensions()?;
150	   150	        Self::configure_engine_environment(&settings)?;
151	   151	        let (request_tx, request_rx) = channel::<EngineRequest>();
152	   152	        // Readiness carries the staging-arena handle out of the engine thread: the context
153	   153	        // itself never leaves that thread, but the handle is `Send + Sync` by design so
154	   154	        // staging calls can bypass the request channel (see the module doc).
155	   155	        let (ready_tx, ready_rx) = channel::<Result<Option<sirius::StagingArena>, String>>();
156	   156	        let thread = std::thread::Builder::new()
157	   157	            .name("sirius-engine".to_string())
158	   158	            .spawn(move || engine_thread(settings.config, request_rx, ready_tx))
159	   159	            .map_err(|err| format!("failed to spawn sirius-engine thread: {err}"))?;
160	   160	        match ready_rx.recv() {
161	   161	            Ok(Ok(staging)) => Ok(Self {
162	   162	                requests: Mutex::new(Some(request_tx)),
163	   163	                thread: Mutex::new(Some(thread)),
164	   164	                staging,
165	   165	            }),
166	   166	            Ok(Err(err)) => Err(err),
167	   167	            Err(_) => Err("sirius-engine thread exited during bring-up".to_string()),
168	   168	        }
169	   169	    }
