173	   173	        let build_dir = std::env::var_os("SIRIUS_BUILD_DIR")
174	   174	            .map(PathBuf::from)
175	   175	            .unwrap_or_else(|| {
176	   176	                PathBuf::from(env!("CARGO_MANIFEST_DIR"))
177	   177	                    .join("../..")
178	   178	                    .join("build/release")
179	   179	            });
180	   180	        let extensions = [
181	   181	            (
182	   182	                "SIRIUS_DUCKDB_PARQUET_EXTENSION",
183	   183	                build_dir.join("extension/parquet/parquet.duckdb_extension"),
184	   184	            ),
185	   185	            (
186	   186	                "SIRIUS_DUCKDB_CORE_FUNCTIONS_EXTENSION",
187	   187	                build_dir.join("extension/core_functions/core_functions.duckdb_extension"),
188	   188	            ),
189	   189	        ];
190	   190	        for (variable, path) in extensions {
191	   191	            if std::env::var_os(variable).is_some() {
192	   192	                continue;
193	   193	            }
194	   194	            if !path.is_file() {
