207	   207	    /// Points the engine's log directory at `<engine_dir>/log` and pins the CUDA device when
208	   208	    /// requested. Environment already set by the operator wins (matching the extension-path
209	   209	    /// precedent above), but an ignored `--gpu-device` is called out rather than dropped silently.
210	   210	    fn configure_engine_environment(settings: &EngineSettings) -> Result<(), String> {
211	   211	        if std::env::var_os("SIRIUS_LOG_DIR").is_none() {
212	   212	            let log_dir = settings.engine_dir.join("log");
213	   213	            std::fs::create_dir_all(&log_dir).map_err(|err| {
214	   214	                format!(
215	   215	                    "failed to create engine log directory {}: {err}",
216	   216	                    log_dir.display()
217	   217	                )
218	   218	            })?;
219	   219	            // SAFETY: this runs before the engine thread and RPC servers start, so no concurrent
220	   220	            // code reads or writes these process environment variables.
221	   221	            unsafe { std::env::set_var("SIRIUS_LOG_DIR", &log_dir) };
222	   222	        }
223	   223	        if let Some(device) = settings.gpu_device {
224	   224	            if let Some(existing) = std::env::var_os("CUDA_VISIBLE_DEVICES") {
225	   225	                warn!(
226	   226	                    existing = %existing.to_string_lossy(),
227	   227	                    requested = device,
228	   228	                    "CUDA_VISIBLE_DEVICES is already set; ignoring --gpu-device"
229	   229	                );
230	   230	            } else {
231	   231	                // SAFETY: same pre-thread-spawn window as above; nothing else touches the
232	   232	                // environment yet.
233	   233	                unsafe { std::env::set_var("CUDA_VISIBLE_DEVICES", device.to_string()) };
234	   234	            }
235	   235	        }
236	   236	        Ok(())
237	   237	    }
238	   238	}
239	   239	
240	   240	/// Engine-thread body: bring up the context, signal readiness, then serve requests until the
241	   241	/// request channel closes. The context is dropped here, on this thread, when the loop ends.
242	   242	fn engine_thread(
243	   243	    config: Option<PathBuf>,
244	   244	    requests: Receiver<EngineRequest>,
245	   245	    ready: Sender<Result<Option<sirius::StagingArena>, String>>,
246	   246	) {
247	   247	    let context = match build_context(config) {
248	   248	        Ok(context) => {
249	   249	            // A send error means the caller is already gone; nothing to serve. The staging
250	   250	            // handle crosses to the caller so leases are served off this thread.
251	   251	            if ready.send(Ok(context.staging_arena())).is_err() {
252	   252	                return;
253	   253	            }
254	   254	            context
255	   255	        }
256	   256	        Err(err) => {
257	   257	            let _ = ready.send(Err(err));
258	   258	            return;
259	   259	        }
260	   260	    };
261	   261	
262	   262	    // Sender fragments whose output is parked on the GPU, waiting for their receivers to be
263	   263	    // dispatched. Parked ONCE per fragment; `parked_slots` maps each destination's SenderSlot to
264	   264	    // (park id, its output stream). Declared after `context` so the fragments drop *first*: a
265	   265	    // fragment borrows the engine it runs on, and the borrow checker enforces the order the C++
266	   266	    // side depends on.
267	   267	    let mut parked: HashMap<u64, ParkedOutput<'_>> = HashMap::new();
268	   268	    let mut parked_slots: HashMap<SenderSlot, (u64, u64)> = HashMap::new();
269	   269	    let mut next_park_id: u64 = 0;
270	   270	    // Why a slot's parked output went away, for the slots the blanket wipe below destroys.
271	   271	    // Without this the wipe is silent and the NEXT export of an unrelated slot reports
272	   272	    // "no parked sender output", which is collateral -- it masks the error that actually killed
273	   273	    // the query. MEASURED: TPC-H q08 reported that error for weeks while the real failure was an
274	   274	    // OOM in HASH_JOIN. Bounded: an entry is dropped as soon as the slot is parked again.
275	   275	    let mut poisoned: HashMap<SenderSlot, String> = HashMap::new();
276	   276	
277	   277	    info!("sirius-engine thread ready");
278	   278	    // One request at a time until the handle (and its sender) is dropped. Every respond-send
279	   279	    // error is ignored: the waiting caller may have been dropped/cancelled.
280	   280	    while let Ok(request) = requests.recv() {
281	   281	        match request {
282	   282	            EngineRequest::Run(request) => {
283	   283	                let result = run_fragment(
284	   284	                    &context,
285	   285	                    &mut parked,
286	   286	                    &mut parked_slots,
287	   287	                    &poisoned,
288	   288	                    &mut next_park_id,
289	   289	                    &request,
290	   290	                );
291	   291	                if let Err(err) = &result {
292	   292	                    // A failed query leaves its parked senders unreachable — the receiver that
293	   293	                    // would have consumed them is the thing that just failed. Dropping them
294	   294	                    // releases the GPU memory their batches hold rather than leaking it for the
295	   295	                    // process's lifetime.
296	   296	                    //
297	   297	                    // The wipe is process-wide, so it also destroys OTHER in-flight fragments'
298	   298	                    // parked output. Record why, and say so out loud: a drain that fails right
299	   299	                    // after this used to report only "no parked sender output", which names the
300	   300	                    // victim and hides the culprit.
301	   301	                    if !parked_slots.is_empty() {
302	   302	                        warn!(
303	   303	                            slots = parked_slots.len(),
304	   304	                            error = %err,
305	   305	                            "discarding every parked sender output on this CN after a fragment failure"
306	   306	                        );
307	   307	                    }
308	   308	                    // Replace, never accumulate: only the most recent wipe can explain a slot
309	   309	                    // that is missing now, and this bounds the map by the live slot count.
310	   310	                    poisoned.clear();
311	   311	                    for slot in parked_slots.keys() {
312	   312	                        poisoned.insert(slot.clone(), err.clone());
313	   313	                    }
314	   314	                    parked.clear();
315	   315	                    parked_slots.clear();
316	   316	                }
317	   317	                let _ = request.respond.send(result);
318	   318	            }
319	   319	            #[cfg(test)]
320	   320	            EngineRequest::Sleep(duration) => std::thread::sleep(duration),
321	   321	            EngineRequest::ExportNext { slot, respond } => {
322	   322	                let result = export_next(&mut parked, &parked_slots, &poisoned, slot);
323	   323	                let _ = respond.send(result);
324	   324	            }
325	   325	            EngineRequest::DropParked { slot, respond } => {
326	   326	                let result = release_slot(&mut parked, &mut parked_slots, &poisoned, &slot);
327	   327	                let _ = respond.send(result);
328	   328	            }
329	   329	            EngineRequest::PinTable { spec, respond } => {
330	   330	                info!(name = %spec.name, tier = spec.tier.as_str(), "pin_table starting");
331	   331	                let started = std::time::Instant::now();
332	   332	                let engine_spec = sirius::PinTableSpec {
333	   333	                    path: spec.path.clone(),
334	   334	                    tier: spec.tier.as_str().to_string(),
335	   335	                    name: spec.name.clone(),
336	   336	                    cols: spec.cols.clone(),
337	   337	                    format: spec.format.clone(),
338	   338	                    schema: spec.schema.clone(),
339	   339	                };
340	   340	                let result = context
341	   341	                    .pin_table(&engine_spec)
342	   342	                    .map_err(|err| format!("pin_table '{}' failed: {err}", spec.name));
343	   343	                info!(
344	   344	                    name = %spec.name,
345	   345	                    elapsed_ms = started.elapsed().as_millis() as u64,
346	   346	                    ok = result.is_ok(),
347	   347	                    "pin_table finished"
348	   348	                );
349	   349	                let _ = respond.send(result);
350	   350	            }
351	   351	            EngineRequest::UnpinTable { name, respond } => {
352	   352	                let result = context
353	   353	                    .unpin_table(&name)
354	   354	                    .map_err(|err| format!("unpin_table '{name}' failed: {err}"));
355	   355	                let _ = respond.send(result);
356	   356	            }
357	   357	        }
358	   358	    }
359	   359	    // Fragments must be gone before the context they borrow.
360	   360	    drop(parked_slots);
361	   361	    drop(parked);
362	   362	    info!("sirius-engine thread shutting down");
363	   363	}
364	   364	
365	   365	/// The error for a slot whose parked output is gone. When the blanket wipe took it, name the
366	   366	/// failure that triggered the wipe — that is the query's REAL error, and reporting only the
367	   367	/// generic message is what made TPC-H q08 look like an exchange bug for weeks when it was an
368	   368	/// OOM in HASH_JOIN.
369	   369	fn missing_slot(poisoned: &HashMap<SenderSlot, String>, slot: &SenderSlot, verb: &str) -> String {
370	   370	    match poisoned.get(slot) {
371	   371	        Some(cause) => format!(
372	   372	            "sender output for {slot:?} was discarded when another fragment on this CN failed: \
373	   373	             {cause}"
374	   374	        ),
375	   375	        None => format!("no parked sender output to {verb} for {slot:?}"),
376	   376	    }
377	   377	}
378	   378	
379	   379	/// Packs the next batch parked under `slot` into a fresh staging lease.
380	   380	fn export_next(
381	   381	    parked: &mut HashMap<u64, ParkedOutput<'_>>,
382	   382	    parked_slots: &HashMap<SenderSlot, (u64, u64)>,
383	   383	    poisoned: &HashMap<SenderSlot, String>,
384	   384	    slot: SenderSlot,
385	   385	) -> Result<Option<StagedBatch>, String> {
386	   386	    let (park_id, stream) = parked_slots
387	   387	        .get(&slot)
388	   388	        .copied()
389	   389	        .ok_or_else(|| missing_slot(poisoned, &slot, "export"))?;
390	   390	    let entry = parked
391	   391	        .get_mut(&park_id)
392	   392	        .ok_or_else(|| format!("parked fragment vanished under {slot:?}"))?;
393	   393	    let batch = entry
394	   394	        .fragment
395	   395	        .export_packed(stream)
396	   396	        .map_err(|err| format!("failed to export a packed batch for {slot:?}: {err}"))?;
397	   397	    Ok(batch.map(|batch| StagedBatch {
398	   398	        metadata: batch.metadata,
399	   399	        offset: batch.offset,
400	   400	        len: batch.len,
401	   401	        rows: Some(batch.rows),
402	   402	    }))
403	   403	}
404	   404	
405	   405	/// Releases one destination's claim on a parked fragment; the fragment (and the GPU memory its
406	   406	/// remaining batches hold) drops when the LAST destination releases. Exactly-once per slot: a
407	   407	/// second release of the same slot is a loud error, never a silent double-drop.
408	   408	fn release_slot(
409	   409	    parked: &mut HashMap<u64, ParkedOutput<'_>>,
410	   410	    parked_slots: &mut HashMap<SenderSlot, (u64, u64)>,
411	   411	    poisoned: &HashMap<SenderSlot, String>,
412	   412	    slot: &SenderSlot,
413	   413	) -> Result<(), String> {
414	   414	    let (park_id, _) = parked_slots
415	   415	        .remove(slot)
416	   416	        .ok_or_else(|| missing_slot(poisoned, slot, "drop"))?;
417	   417	    let entry = parked
418	   418	        .get_mut(&park_id)
419	   419	        .ok_or_else(|| format!("parked fragment vanished under {slot:?}"))?;
420	   420	    entry.outstanding -= 1;
421	   421	    if entry.outstanding == 0 {
422	   422	        parked.remove(&park_id);
423	   423	    }
424	   424	    Ok(())
425	   425	}
426	   426	
427	   427	/// Runs one fragment on the engine thread, guaranteeing that the staging leases its remote
428	   428	/// inputs sit in are released exactly once — immediately after each successful push, or in a
429	   429	/// sweep when the run fails partway (a leaked lease would pin the arena for later queries).
430	   430	fn run_fragment<'ctx>(
431	   431	    context: &'ctx SiriusContext,
432	   432	    parked: &mut HashMap<u64, ParkedOutput<'ctx>>,
433	   433	    parked_slots: &mut HashMap<SenderSlot, (u64, u64)>,
434	   434	    poisoned: &HashMap<SenderSlot, String>,
435	   435	    next_park_id: &mut u64,
436	   436	    request: &ExecuteRequest,
437	   437	) -> Result<Option<FragmentResult>, String> {
438	   438	    // Every engine-thread line of this run (relay, remote push, cardinality, lease sweep) carries
439	   439	    // the StarRocks ids; the span's close event is the engine-side elapsed time of the run.
440	   440	    let span = tracing::info_span!(
441	   441	        "fragment",
442	   442	        query_id = tracing::field::Empty,
443	   443	        fragment_instance_id = tracing::field::Empty
444	   444	    );
445	   445	    if let Some(id) = request.label.query_id {
446	   446	        span.record("query_id", tracing::field::display(id));
447	   447	    }
448	   448	    if let Some(id) = request.label.fragment_instance_id {
449	   449	        span.record("fragment_instance_id", tracing::field::display(id));
450	   450	    }
451	   451	    let _entered = span.enter();
452	   452	    let mut released = std::collections::HashSet::new();
453	   453	    let result = run_fragment_inner(
454	   454	        context,
455	   455	        parked,
456	   456	        parked_slots,
457	   457	        poisoned,
458	   458	        next_park_id,
459	   459	        request,
460	   460	        &mut released,
461	   461	    );
462	   462	    if result.is_err() {
463	   463	        for (_, _, batches) in &request.remote_inputs {
464	   464	            for batch in batches {
465	   465	                // `len == 0` batches never held a lease (metadata-only), and offsets in
466	   466	                // `released` already went back in the push loop.
467	   467	                if batch.len == 0 || released.contains(&batch.offset) {
468	   468	                    continue;
469	   469	                }
470	   470	                if let Err(err) = context.staging_release(batch.offset) {
471	   471	                    warn!(
472	   472	                        offset = batch.offset,
473	   473	                        error = %err,
474	   474	                        "failed to release a remote-input staging lease after a fragment error"
475	   475	                    );
476	   476	                }
477	   477	            }
478	   478	        }
479	   479	    }
480	   480	    result
481	   481	}
482	   482	
483	   483	/// Runs one fragment on the engine thread: declare its input streams, relay every parked sender
484	   484	/// and push every staged remote batch into them, execute, then either park the output or return
485	   485	/// the rows. Records each released remote-input lease offset in `released`.
486	   486	fn run_fragment_inner<'ctx>(
487	   487	    context: &'ctx SiriusContext,
488	   488	    parked: &mut HashMap<u64, ParkedOutput<'ctx>>,
489	   489	    parked_slots: &mut HashMap<SenderSlot, (u64, u64)>,
490	   490	    poisoned: &HashMap<SenderSlot, String>,
491	   491	    next_park_id: &mut u64,
492	   492	    request: &ExecuteRequest,
493	   493	    released: &mut std::collections::HashSet<u64>,
494	   494	) -> Result<Option<FragmentResult>, String> {
495	   495	    let mut fragment = context
496	   496	        .fragment()
497	   497	        .map_err(|err| format!("failed to create fragment: {err}"))?;
498	   498	
499	   499	    // Name the engine's Quent Query after the StarRocks ids before build() opens it, so the
500	   500	    // telemetry of this fragment and of its peers on other CNs share one query group.
501	   501	    if let Some(query_label) = request.label.query_label() {
502	   502	        let session_label = request.label.session_label().unwrap_or_default();
503	   503	        fragment
504	   504	            .set_query_label(&query_label, &session_label)
505	   505	            .map_err(|err| format!("failed to label fragment {query_label}: {err}"))?;
506	   506	    }
507	   507	
508	   508	    for schema in &request.stream_inputs {
509	   509	        let stream_id = stream_id_of(schema.node_id)?;
510	   510	        for column in &schema.columns {
511	   511	            fragment
512	   512	                .declare_input_column(stream_id, &column.name, &column.ty)
513	   513	                .map_err(|err| {
514	   514	                    format!(
515	   515	                        "failed to declare column {} of stream {stream_id}: {err}",
516	   516	                        column.name
517	   517	                    )
518	   518	                })?;
519	   519	        }
520	   520	        let senders = request
521	   521	            .inputs
522	   522	            .iter()
523	   523	            .find(|(node_id, _)| *node_id == schema.node_id)
524	   524	            .map(|(_, senders)| senders.as_slice())
525	   525	            .unwrap_or_default();
526	   526	        let remote_senders = request
527	   527	            .remote_inputs
528	   528	            .iter()
529	   529	            .filter(|(node_id, _, _)| *node_id == schema.node_id)
530	   530	            .map(|(_, sender_id, _)| *sender_id)
531	   531	            .collect::<Vec<_>>();
532	   532	        if senders.is_empty() && remote_senders.is_empty() {
533	   533	            return Err(format!(
534	   534	                "exchange node {} is read as a stream but no sender output — parked or remote — \
535	   535	                 exists for it",
536	   536	                schema.node_id
537	   537	            ));
538	   538	        }
539	   539	        for sender_id in senders
540	   540	            .iter()
541	   541	            .map(|slot| slot.sender_id)
542	   542	            .chain(remote_senders)
543	   543	        {
544	   544	            let sender_id =
545	   545	                u32::try_from(sender_id).map_err(|_| format!("negative sender id {sender_id}"))?;
546	   546	            fragment
547	   547	                .declare_input_sender(stream_id, sender_id)
548	   548	                .map_err(|err| format!("failed to declare sender on stream {stream_id}: {err}"))?;
549	   549	        }
550	   550	
551	   551	        // The CN already holds every input of this fragment — parked local sender outputs and
552	   552	        // staged remote batches — so it can declare the stream's EXACT row count and let
553	   553	        // DuckDB's optimizer size join order / build-side selection (a stream source binds with
554	   554	        // no rows behind it, so undeclared streams all estimate cardinality 1: the q07 2-CN
555	   555	        // regression built its hash join on a multi-GB stream while a 2-row stream probed).
556	   556	        // Best-effort by design: when any contributor's count is unknown (a spilled parked
557	   557	        // batch, a remote frame that predates the wire's `rows` field), skip the declaration
558	   558	        // and keep the legacy blind planning for this stream rather than failing the fragment.
559	   559	        let local_rows: Option<u64> = senders
560	   560	            .iter()
561	   561	            .map(|slot| {
562	   562	                let (park_id, sender_stream) = parked_slots.get(slot).copied()?;
563	   563	                let entry = parked.get(&park_id)?;
564	   564	                entry.fragment.output_row_count(sender_stream).ok()
565	   565	            })
566	   566	            .sum();
567	   567	        let remote_rows: Option<u64> = request
568	   568	            .remote_inputs
569	   569	            .iter()
570	   570	            .filter(|(node_id, _, _)| *node_id == schema.node_id)
571	   571	            .flat_map(|(_, _, batches)| batches.iter().map(|batch| batch.rows))
572	   572	            .sum();
573	   573	        match (local_rows, remote_rows) {
574	   574	            (Some(local), Some(remote)) => {
575	   575	                let rows = local + remote;
576	   576	                fragment
577	   577	                    .declare_input_cardinality(stream_id, rows)
578	   578	                    .map_err(|err| {
579	   579	                        format!("failed to declare cardinality of stream {stream_id}: {err}")
580	   580	                    })?;
581	   581	                info!(stream_id, rows, "declared input stream cardinality");
582	   582	            }
583	   583	            _ => warn!(
584	   584	                stream_id,
585	   585	                "input stream row count unknown; planning without a declared cardinality"
586	   586	            ),
587	   587	        }
588	   588	    }
589	   589	
590	   590	    // An intermediate fragment sinks into one output stream per destination (stream i belongs
591	   591	    // to destination outputs[i]); a result fragment declares none and produces Arrow instead.
592	   592	    for stream in 0..request.outputs.len() as u64 {
593	   593	        fragment
594	   594	            .declare_output(stream)
595	   595	            .map_err(|err| format!("failed to declare fragment output stream {stream}: {err}"))?;
596	   596	    }
597	   597	    if request.broadcast && request.outputs.len() > 1 {
598	   598	        fragment
599	   599	            .declare_output_broadcast()
600	   600	            .map_err(|err| format!("failed to declare the broadcast output mode: {err}"))?;
601	   601	    } else if !request.hash_keys.is_empty() && request.outputs.len() > 1 {
602	   602	        for &key in &request.hash_keys {
603	   603	            let key = u32::try_from(key).map_err(|_| format!("hash key column {key} overflows"))?;
604	   604	            fragment
605	   605	                .declare_output_hash_key(key)
606	   606	                .map_err(|err| format!("failed to declare hash key column {key}: {err}"))?;
607	   607	        }
608	   608	    }
609	   609	
610	   610	    fragment
611	   611	        .build(&request.plan)
612	   612	        .map_err(|err| format!("failed to plan fragment: {err}"))?;
613	   613	
614	   614	    // The fragment boundary itself: each sender's batches move into this fragment's input stream
615	   615	    // as native handles. Nothing is converted, written, or copied.
616	   616	    for schema in &request.stream_inputs {
617	   617	        let stream_id = stream_id_of(schema.node_id)?;
618	   618	        let senders = request
619	   619	            .inputs
620	   620	            .iter()
621	   621	            .find(|(node_id, _)| *node_id == schema.node_id)
622	   622	            .map(|(_, senders)| senders.as_slice())
623	   623	            .unwrap_or_default();
624	   624	        for slot in senders {
625	   625	            let (park_id, sender_stream) = parked_slots
626	   626	                .get(slot)
627	   627	                .copied()
628	   628	                .ok_or_else(|| format!("no parked sender output for {slot:?}"))?;
629	   629	            let sender = parked
630	   630	                .get_mut(&park_id)
631	   631	                .ok_or_else(|| format!("parked fragment vanished under {slot:?}"))?;
632	   632	            let sender_id = u32::try_from(slot.sender_id)
633	   633	                .map_err(|_| format!("negative sender id {}", slot.sender_id))?;
634	   634	            let moved = fragment
635	   635	                .relay_from(&mut sender.fragment, sender_stream, stream_id, sender_id)
636	   636	                .map_err(|err| format!("failed to relay sender {sender_id}: {err}"))?;
637	   637	            // This destination's stream is drained; release its claim (the fragment drops with
638	   638	            // the last claim, freeing the GPU batches).
639	   639	            release_slot(parked, parked_slots, poisoned, slot)?;
640	   640	            info!(
641	   641	                stream_id,
642	   642	                sender_id,
643	   643	                batches = moved,
644	   644	                "relayed native batches across a fragment boundary"
645	   645	            );
646	   646	        }
647	   647	    }
648	   648	
649	   649	    // Remote senders: their packed batches already sit in this CN's staging arena. Push each
650	   650	    // (deep copy into pool memory), release its lease immediately — copy-out-on-arrival makes
651	   651	    // that safe — then close the sender.
652	   652	    for (node_id, sender_id, batches) in &request.remote_inputs {
653	   653	        let stream_id = stream_id_of(*node_id)?;
654	   654	        let sender = u32::try_from(*sender_id)
655	   655	            .map_err(|_| format!("negative remote sender id {sender_id}"))?;
656	   656	        for batch in batches {
