220+85	    /// Queues a sender-only fragment on the dispatch worker. Returns `Ok(false)` when the
221+85	    /// fragment must take the inline path (exchange receiver, RESULT_SINK root, survey mode, or
222+85	    /// the switch is off); descriptor tables are resolved at arrival either way, so the FE's
223+85	    /// per-query descriptor cache protocol sees the same order as before.
224+85	    fn try_dispatch_sender(
225+85	        &self,
226+85	        params: &TExecPlanFragmentParams,
227+85	    ) -> std::result::Result<bool, String> {
228+85	        if !self
229+85	            .core
230+85	            .async_sender_dispatch
231+85	            .load(std::sync::atomic::Ordering::Relaxed)
232+85	            || std::env::var_os("SIRIUS_CN_TRANSLATE_ONLY").is_some()
233+85	            || !ServiceCore::receiver_exchanges(params)?.is_empty()
234+85	            || ServiceCore::is_mysql_result_sink(params)?
235+85	        {
236+85	            return Ok(false);
237+85	        }
238+85	        let params = self.core.resolve_descriptor_table(params)?;
239+85	        self.dispatch(ReadyFragment {
240+85	            params,
241+85	            inputs: Vec::new(),
242+85	        })?;
