246+85	    /// Hands a ready receiver to the dispatch worker so this RPC thread returns immediately
247+85	    /// instead of blocking on the receiver's whole execution.
248+85	    fn dispatch(&self, ready: ReadyFragment) -> std::result::Result<(), String> {
249+85	        self.ready_fragments.send(ready).map_err(|_| {
250+85	            "fragment dispatch worker has exited; cannot execute receiver fragment".to_string()
251+85	        })
252+85	    }
253+85	
254+85	    /// Dispatches every receiver this fragment readied, THEN joins its remote drains.
255+85	    ///
256+85	    /// The order is the whole change: dispatch puts the receiver on the worker thread while the
257+85	    /// transport thread is still draining this sender's remote destinations, instead of the
258+85	    /// receiver waiting out the full (N-1)-destination drain first. The RPC still does not
259+85	    /// return until every drain has been joined — the FE may only be told the sender succeeded
260+85	    /// once each destination's copy is actually across the wire.
261+85	    ///
262+85	    /// A receiver dispatched here can now run concurrently with its own query's drains. That
263+85	    /// costs nothing in correctness (its sender set was already complete, so it reads no data
264+85	    /// the drains produce) but it does mean the parked batches of the not-yet-drained
265+85	    /// destinations stay resident while it computes — the deliberate memory-for-latency trade.
266+85	    fn dispatch_then_join(&self, outcome: FragmentOutcome) -> std::result::Result<(), String> {
267+85	        let mut dispatch_error = None;
268+85	        for ready in outcome.ready {
269+85	            if let Err(err) = self.dispatch(ready) {
270+85	                dispatch_error.get_or_insert(err);
271+85	            }
272+85	        }
273+85	        // Joined unconditionally, even when dispatch failed: the drains are already in flight.
274+85	        let drain_result = outcome.drains.join();
275+85	        match (drain_result, dispatch_error) {
276+85	            (Ok(()), None) => Ok(()),
277+85	            (Ok(()), Some(dispatch)) => Err(dispatch),
278+85	            // A drain failure names the destination and the transport fault, so it is the more
279+85	            // useful cause to hand the FE; a dispatch failure only ever means "this CN is
280+85	            // shutting down". Report the drain error, keep the other in the log.
281+85	            (Err(drain), dispatch) => {
282+85	                if let Some(dispatch) = dispatch {
283+85	                    tracing::error!(error = %dispatch, "receiver dispatch also failed");
284+85	                }
285+85	                Err(drain)
286+85	            }
287+85	        }
288+85	    }
289+85	}
