291+85	/// Executes ready receiver fragments sequentially, off the RPC threads.
292+85	///
293+85	/// Exits when every service clone has dropped its sender; the worker then releases its core
294+85	/// handle (and with it the executor), keeping engine teardown ordered.
295+85	fn dispatch_worker(core: Arc<ServiceCore>, inbox: mpsc::Receiver<ReadyFragment>) {
296+85	    while let Ok(ready) = inbox.recv() {
297+85	        // A receiver can itself be a sender whose completion readies further receivers (a
298+85	        // middle fragment, possibly fanning out); chase the whole set inline — this thread is
299+85	        // already off the RPC path.
300+85	        let mut queue = vec![ready];
301+85	        while let Some(ready) = queue.pop() {
302+85	            queue.extend(core.run_ready_fragment(ready));
303+85	        }
304+85	    }
305+85	}
