1322	    /// Translates a receiver whose sender set is complete, binding each exchange to the input
1323	    /// stream its senders parked into (or staged, for remote senders), and runs it. Returns the
1324	    /// next receiver when this one's own sink completed another sender set.
1325	    fn execute_ready_fragment(
1326	        &self,
1327	        ready: ReadyFragment,
1328	    ) -> std::result::Result<FragmentOutcome, String> {
1329	        let exchange_inputs = ready
1330	            .inputs
1331	            .iter()
1332	            .map(|input| {
1333	                let names = input
1334	                    .sources
1335	                    .first()
1336	                    .map(|source| source.names().to_vec())
1337	                    .ok_or_else(|| {
1338	                        format!("exchange node {} has no sender source", input.node_id)
1339	                    })?;
1340	                // Local and remote senders alike must agree on the schema they produced; the
1341	                // first source is the reference, disagreement fails the query.
1342	                if input
1343	                    .sources
1344	                    .iter()
1345	                    .any(|source| source.names() != names.as_slice())
1346	                {
1347	                    return Err("exchange senders produced different output names".to_string());
1348	                }
1349	                let stream_id = u64::try_from(input.node_id)
1350	                    .map_err(|_| format!("negative exchange node id {}", input.node_id))?;
1351	                Ok(ExchangeInput {
1352	                    node_id: input.node_id,
1353	                    stream_view: sirius_stream_view_name(stream_id),
1354	                    names,
1355	                })
1356	            })
1357	            .collect::<Result<Vec<_>, String>>()?;
1358	        // A receiver translates when its sender set completes, not at arrival, so pair its plan
1359	        // dump with a fresh params dump here (the arrival-time dump carried no plan yet).
1360	        let dump_seq = Self::dump_fragment(&ready.params);
1361	        let translated =
1362	            self.translate_fragment_logged_with_inputs(&ready.params, &exchange_inputs, dump_seq)?;
1363	        let mut inputs: Vec<(i32, Vec<SenderSlot>)> = Vec::new();
1364	        let mut remote_inputs: Vec<(i32, i32, Vec<StagedBatch>)> = Vec::new();
1365	        for input in ready.inputs {
1366	            let mut slots = Vec::new();
1367	            for source in input.sources {
1368	                match source {
1369	                    SenderSource::LocalParked { slot, .. } => slots.push(slot),
1370	                    SenderSource::Remote {
1371	                        sender_id,
1372	                        batches,
1373	                        closed,
1374	                        ..
1375	                    } => {
1376	                        // take_ready only releases complete sender sets; an open remote source
1377	                        // here is a rendezvous bug, not a recoverable state.
1378	                        if !closed {
1379	                            return Err(format!(
1380	                                "exchange node {} became ready with remote sender {sender_id} \
1381	                                 still open",
1382	                                input.node_id
1383	                            ));
1384	                        }
1385	                        remote_inputs.push((input.node_id, sender_id, batches));
1386	                    }
1387	                }
1388	            }
1389	            if !slots.is_empty() {
1390	                inputs.push((input.node_id, slots));
1391	            }
1392	        }
1393	        self.execute_fragment_with_inputs(&ready.params, translated, inputs, remote_inputs)
1394	    }
