1396	    /// Finds every exchange receiver in a fragment and each expected sender count.
1397	    fn receiver_exchanges(
1398	        params: &TExecPlanFragmentParams,
1399	    ) -> std::result::Result<Vec<(i32, usize)>, String> {
1400	        let exchange_nodes = params
1401	            .fragment
1402	            .as_ref()
1403	            .and_then(|fragment| fragment.plan.as_ref())
1404	            .map(|plan| {
1405	                plan.nodes
1406	                    .iter()
1407	                    .filter(|node| {
1408	                        node.node_type == starrocks_thrift::plan_nodes::TPlanNodeType::EXCHANGE_NODE
1409	                    })
1410	                    .map(|node| node.node_id)
1411	                    .collect::<Vec<_>>()
1412	            })
1413	            .unwrap_or_default();
1414	        exchange_nodes
1415	            .into_iter()
1416	            .map(|node_id| {
1417	                let expected = params
1418	                    .params
1419	                    .as_ref()
1420	                    .and_then(|exec| exec.per_exch_num_senders.get(&node_id))
1421	                    .copied()
1422	                    .ok_or_else(|| {
1423	                        format!("EXCHANGE_NODE {node_id} is missing per_exch_num_senders")
1424	                    })?;
1425	                let expected = usize::try_from(expected).map_err(|_| {
1426	                    format!("EXCHANGE_NODE {node_id} has negative sender count {expected}")
1427	                })?;
1428	                Ok((node_id, expected))
1429	            })
1430	            .collect()
1431	    }
