1433	    /// Converts a StarRocks thrift plan fragment to Substrait, logs substrait-explain output, and
1434	    /// returns the translated plan for execution.
1435	    #[instrument(skip_all)]
1436	    fn translate_fragment_logged(
1437	        &self,
1438	        params: &TExecPlanFragmentParams,
1439	        dump_seq: Option<u64>,
1440	    ) -> std::result::Result<TranslatedPlan, String> {

1540	    fn run_labeled(
1541	        &self,
1542	        role: &'static str,
1543	        run: FragmentRun<'_>,
1544	    ) -> std::result::Result<Option<FragmentResult>, String> {
